</Group>

<Group description="Sidebar" selector="div.sidebar-container">
  <Variable name="sidebar.backgroundColorTop"
      description="Background color (Top)"
      type="color"
      default="#f7f7f7"  value="#1d1d1d"/>
  <Variable name="sidebar.backgroundColorTopHD"
      description="Background color (Top) - HD"
      type="color"
      default="rgba(255, 255, 255, 1)"  value="#1d1d1d"/>
  <Variable name="sidebar.backgroundColorBottom"
      description="Background color (Bottom)"
      type="color"
      default="#fff"  value="#1d1d1d"/>
  <Variable name="sidebar.separator.color"
      description="Separator color"
      type="color"
      default="#ccc"  value="#cccccc"/>
  <Variable name="widget.title.color"
      description="Gadget title color"
      type="color"
      default="#212121"  value="#c5c1c1"/>
  <Variable name="sidebar.icons.color"
      description="Sidebar icons color"
      type="color"
      default="#707070"  value="#ffffff"/>
</Group>

<Group description="Header" selector="header.blog-header">
  <Variable name="header.profileImageUrl"
      description="Header profile image URL"
      type="string"
      default="https://via.placeholder.com/48"
      value="https://via.placeholder.com/48"/>
</Group>

<Group description="Author profile" selector='.widget.Profile'>
  <Variable name="profile.title.color" description="Profile title color"
      type="color"
      default="rgba(0,0,0,0.52)"  value="#c5c1c1"/>
  <Variable name="profile.text.color" description="Profile text color"
      type="color"
      default="rgba(0, 0, 0, 0.54)"  value="rgba(238, 238, 238, 0.54)"/>
  <Variable name="profile.link.color" description="Profile link color"
      type="color"
      default="$(posts.title.color)"  value="#ffffff"/>
</Group>

<Group description="Labels" selector=".widget.Label">
  <Variable name="labels.text.color"
      description="Label text color"
      type="color"
      default="$(body.link.color)"  value="#ffffff"/>
  <Variable name="labels.background.color"
      description="Label background color"
      type="color"
      red="$(labels.text.color.red)"
      green="$(labels.text.color.green)"
      blue="$(labels.text.color.blue)"
      default="rgba($red, $green, $blue, 0.05)"  value="#444444"/>
</Group>

<Group description="Attribution" selector=".widget.Attribution">
  <Variable name="attribution.text.color" description="Attribution text color"
      type="color"
      default="$(body.text.color)"  value="#9ba2a8"/>
  <Variable name="attribution.link.color" description="Attribution link color"
      type="color"
      default="$(body.link.color)"  value="#2196f3"/>
  <Variable name="attribution.icon.color" description="Attribution icon color"
      type="color"
      default="#707070"
      hideEditor="true"  value="#ffffff"/>
</Group>

<Group description="Widths">
  <Variable name="sidebar.width" description="Sidebar width" type="length"
            min="100px" max="1000px" default="284px"  value="284px"/>
  <Variable name="content.width" description="Content width" type="length"
            min="600px" max="2400px" default="922px"  value="922px"/>
  <Variable name="content.margin" description="Content margin" type="length"
            min="0px" max="1000px" default="117px"  value="117px"/>
</Group>
 */

/*!************************************************
 * Blogger Template Style
 * Name: Contempo (Custom Redesign)
 * Redesigned to match redwan.work main site
 **************************************************/

/* ============================================
   CSS VARIABLES FOR THEME SYSTEM
   ============================================ */
:root {
  /* Light Mode Colors (Default) */
  --radius: 0.75rem;

  /* HSL Color Variables - Light Mode */
  --background: 0 0% 100%;
  --foreground: 0 0% 3.9%;
  --card: 0 0% 100%;
  --card-foreground: 0 0% 3.9%;
  --popover: 0 0% 100%;
  --popover-foreground: 0 0% 3.9%;
  --primary: 221.2 83.2% 53.3%;
  --primary-foreground: 210 40% 98%;
  --secondary: 210 40% 96.1%;
  --secondary-foreground: 222.2 47.4% 11.2%;
  --muted: 210 40% 96.1%;
  --muted-foreground: 215.4 16.3% 46.9%;
  --accent: 210 40% 96.1%;
  --accent-foreground: 222.2 47.4% 11.2%;
  --destructive: 0 84.2% 60.2%;
  --destructive-foreground: 210 40% 98%;
  --border: 214.3 31.8% 91.4%;
  --input: 214.3 31.8% 91.4%;
  --ring: 221.2 83.2% 53.3%;

  /* Convenience variables */
  --bg: hsl(var(--background));
  --bg-elevated: hsl(var(--card));
  --body-bg: hsl(var(--background));
  --text: hsl(var(--foreground));
  --text-muted: hsl(var(--muted-foreground));
  --border-color: hsl(var(--border));
  --accent-color: hsl(var(--primary));
  --accent-hover: hsl(var(--primary) / 0.9);

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
}

/* Dark Mode Colors */
[data-theme="dark"] {
  --background: 222.2 84% 4.9%;
  --foreground: 210 40% 98%;
  --card: 222.2 84% 4.9%;
  --card-foreground: 210 40% 98%;
  --popover: 222.2 84% 4.9%;
  --popover-foreground: 210 40% 98%;
  --primary: 217.2 91.2% 59.8%;
  --primary-foreground: 222.2 47.4% 11.2%;
  --secondary: 217.2 32.6% 17.5%;
  --secondary-foreground: 210 40% 98%;
  --muted: 217.2 32.6% 17.5%;
  --muted-foreground: 215 20.2% 65.1%;
  --accent: 217.2 32.6% 17.5%;
  --accent-foreground: 210 40% 98%;
  --destructive: 0 62.8% 30.6%;
  --destructive-foreground: 210 40% 98%;
  --border: 217.2 32.6% 17.5%;
  --input: 217.2 32.6% 17.5%;
  --ring: 224.3 76.3% 48%;

  /* Convenience variables */
  --bg: hsl(var(--background));
  --bg-elevated: hsl(var(--card));
  --body-bg: hsl(var(--background));
  --text: hsl(var(--foreground));
  --text-muted: hsl(var(--muted-foreground));
  --border-color: hsl(var(--border));
  --accent-color: hsl(var(--primary));
  --accent-hover: hsl(var(--primary) / 0.9);

  /* Adjusted shadows for dark mode */
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.3);
  --shadow: 0 1px 3px 0 rgb(0 0 0 / 0.4), 0 1px 2px -1px rgb(0 0 0 / 0.4);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.4), 0 2px 4px -2px rgb(0 0 0 / 0.4);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.5), 0 4px 6px -4px rgb(0 0 0 / 0.5);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.6), 0 8px 10px -6px rgb(0 0 0 / 0.6);
}

/* ============================================
   BASE STYLES
   ============================================ */
* {
  transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

body{
overflow-wrap:break-word;
word-break:break-word;
word-wrap:break-word;
background: var(--body-bg, var(--bg));
color: var(--text);
font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.hidden{
display:none
}
.invisible{
visibility:hidden
}

/* ============================================
   MODERN LAYOUT & CONTAINER STYLES
   ============================================ */
.page {
  background: var(--body-bg, var(--bg));
  min-height: 100vh;
}

.centered {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1rem;
}

@media (min-width: 640px) {
  .centered {
    padding: 0 1.5rem;
  }
}

@media (min-width: 1024px) {
  .centered {
    padding: 0 2rem;
  }
}

/* ============================================
   MODERN CARD STYLES FOR POSTS
   ============================================ */
#page_body .FeaturedPost,
.Blog .blog-posts .post-outer-container {
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 2rem;
  margin-bottom: 1.5rem;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

#page_body .FeaturedPost:hover,
.Blog .blog-posts .post-outer-container:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.post-outer-container {
  margin-bottom: 1.5rem;
}

/* Post Titles */
.post-title {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.3;
  margin: 0 0 1rem 0;
  color: var(--text);
}

.post-title a {
  color: var(--text);
  text-decoration: none;
  transition: color 0.2s ease;
}

.post-title a:hover {
  color: var(--accent-color);
}

/* Post Body */
.post-body {
  color: var(--text);
  font-size: 1rem;
  line-height: 1.75;
  margin: 1rem 0;
}

.post-body h1,
.post-body h2,
.post-body h3,
.post-body h4,
.post-body h5,
.post-body h6 {
  color: var(--text);
  font-weight: 600;
  line-height: 1.25;
  margin: 1.5rem 0 0.75rem 0;
}

.post-body h1 { font-size: 2rem; }
.post-body h2 { font-size: 1.5rem; }
.post-body h3 { font-size: 1.25rem; }
.post-body h4 { font-size: 1.125rem; }

.post-body p {
  margin: 0.75rem 0;
}

.post-body a {
  color: var(--accent-color);
  text-decoration: underline;
}

.post-body a:hover {
  color: var(--accent-hover);
}

.post-body img {
  max-width: 100%;
  height: auto;
  border-radius: calc(var(--radius) * 0.5);
  margin: 1rem 0;
}

.post-body code {
  background: var(--muted);
  color: var(--text);
  padding: 0.125rem 0.375rem;
  border-radius: 0.25rem;
  font-size: 0.875rem;
  font-family: 'Consolas', 'Monaco', 'Courier New', monospace;
}

.post-body pre {
  background: var(--muted);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 1rem;
  overflow-x: auto;
  margin: 1rem 0;
}

.post-body pre code {
  background: transparent;
  padding: 0;
}

.post-body blockquote {
  border-left: 4px solid var(--accent-color);
  padding-left: 1rem;
  margin: 1rem 0;
  color: var(--text-muted);
  font-style: italic;
}

.post-body ul,
.post-body ol {
  margin: 0.75rem 0;
  padding-left: 1.5rem;
}

.post-body li {
  margin: 0.375rem 0;
}

/* Post Metadata */
.post-header,
.post-footer {
  color: var(--text-muted);
  font-size: 0.875rem;
  margin: 1rem 0;
}

.byline {
  color: var(--text-muted);
  margin-right: 1rem;
}

.byline:last-child {
  margin-right: 0;
}

/* Post Snippets/Thumbnails */
.snippet-thumbnail {
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 1rem;
}

.snippet-thumbnail img {
  width: 100%;
  height: auto;
  display: block;
}

/* ============================================
   HEADER STYLES (MATCH MAIN SITE)
   ============================================ */
.centered-top-container {
  background: var(--bg);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 50;
  backdrop-filter: blur(8px);
  background: var(--bg) / 95%;
}

.centered-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 5rem;
  padding: 0 1rem;
}

@media (min-width: 1024px) {
  .centered-top {
    min-height: 6rem;
  }
}

/* Blog Title/Logo */
.blog-name {
  flex: 1;
}

.Header h1 {
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0;
  color: var(--text);
  text-align: left;
}

.Header h1 a,
.Header h1 a:hover,
.Header h1 a:visited {
  color: var(--text);
  text-decoration: none;
}

.Header p {
  display: none; /* Hide description in compact header */
}

/* ============================================
   NAVIGATION (PAGELIST)
   ============================================ */
.widget.PageList {
  margin: 0;
}

.widget.PageList ul {
  display: flex;
  gap: 1.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.widget.PageList li {
  display: inline-block;
  margin: 0;
}

.widget.PageList li a {
  color: var(--text-muted);
  text-decoration: none;
  font-weight: 500;
  font-size: 0.875rem;
  transition: color 0.2s ease;
}

.widget.PageList li a:hover,
.widget.PageList li.selected a {
  color: var(--accent-color);
}

/* Mobile Menu Button */
.hamburger-menu {
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
}

@media (min-width: 1024px) {
  .hamburger-menu {
    display: none;
  }
}

/* ============================================
   THEME TOGGLE BUTTON
   ============================================ */
.theme-toggle {
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  margin-left: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius);
  transition: background-color 0.2s ease;
}

.theme-toggle:hover {
  background: var(--accent) / 10%;
}

.theme-toggle svg {
  width: 1.25rem;
  height: 1.25rem;
  fill: var(--text);
}

.theme-toggle .sun-icon {
  display: none;
}

.theme-toggle .moon-icon {
  display: block;
}

[data-theme="dark"] .theme-toggle .sun-icon {
  display: block;
}

[data-theme="dark"] .theme-toggle .moon-icon {
  display: none;
}

/* ============================================
   SIDEBAR & WIDGET STYLES
   ============================================ */
.sidebar-container {
  background: var(--bg);
}

.sidebar_bottom {
  padding: 2rem 1rem;
}

.sidebar_bottom .widget {
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
}

.sidebar_bottom .widget h2,
.sidebar_bottom .widget .title {
  color: var(--text);
  font-size: 1.125rem;
  font-weight: 600;
  margin: 0 0 1rem 0;
}

.sidebar_bottom .widget ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.sidebar_bottom .widget li {
  margin: 0.5rem 0;
  padding: 0;
}

.sidebar_bottom .widget a {
  color: var(--text-muted);
  text-decoration: none;
  transition: color 0.2s ease;
}

.sidebar_bottom .widget a:hover {
  color: var(--accent-color);
}

/* Popular Posts Widget */
.PopularPosts .item-thumbnail {
  border-radius: calc(var(--radius) * 0.5);
  overflow: hidden;
  margin-bottom: 0.5rem;
}

.PopularPosts .item-thumbnail img {
  width: 100%;
  height: auto;
  display: block;
}

.PopularPosts .item-title {
  font-weight: 500;
  font-size: 0.9375rem;
  margin: 0.5rem 0;
}

/* Labels Widget */
.Label .pill-button {
  background: var(--muted);
  border: 1px solid var(--border-color);
  color: var(--text);
  border-radius: 0.75rem;
  padding: 0.375rem 1rem;
  font-size: 0.875rem;
  display: inline-block;
  margin: 0.25rem;
  transition: all 0.2s ease;
}

.Label .pill-button:hover {
  background: var(--accent-color);
  color: var(--bg);
  border-color: var(--accent-color);
}

/* Archive Widget */
.BlogArchive ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.BlogArchive li {
  font-size: 0.9375rem;
  padding: 0.375rem 0;
}

.BlogArchive .post-count {
  color: var(--text-muted);
  font-size: 0.875rem;
  margin-left: 0.5rem;
}

/* ============================================
   SEARCH STYLES
   ============================================ */
.search {
  display: flex;
  align-items: center;
}

.search form {
  display: flex;
  align-items: center;
  width: 100%;
}

.search-input input {
  background: var(--muted);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  color: var(--text);
  padding: 0.5rem 1rem;
  font-size: 1rem;
  outline: none;
  width: 100%;
  transition: border-color 0.2s ease;
}

.search-input input:focus {
  border-color: var(--accent-color);
}

.search-input input::placeholder {
  color: var(--text-muted);
}

.search-action {
  background: var(--accent-color);
  color: var(--bg);
  border: none;
  border-radius: var(--radius);
  padding: 0.5rem 1.5rem;
  font-weight: 500;
  cursor: pointer;
  margin-left: 0.5rem;
  transition: background-color 0.2s ease;
}

.search-action:hover {
  background: var(--accent-hover);
}

.search-action:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ============================================
   COMMENTS SECTION
   ============================================ */
#comments {
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 2rem;
  margin-top: 2rem;
}

#comments h3,
#comments h4 {
  color: var(--text);
  font-weight: 600;
  margin: 0 0 1rem 0;
}

.comment {
  border-bottom: 1px solid var(--border-color);
  padding: 1rem 0;
}

.comment:last-child {
  border-bottom: none;
}

.comment .comment-header .user,
.comment .comment-header .user a {
  color: var(--text);
  font-weight: 600;
}

.comment .comment-content,
.comment .comment-body {
  color: var(--text);
  margin-top: 0.5rem;
}

.comment .comment-header .datetime,
.comment .comment-header .datetime a {
  color: var(--text-muted);
  font-size: 0.875rem;
}

.comment .comment-actions a {
  color: var(--accent-color);
  text-decoration: none;
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
}

.comment .comment-actions a:hover {
  color: var(--accent-hover);
}

/* ============================================
   PAGINATION/BLOG PAGER
   ============================================ */
.blog-pager {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin: 2rem 0;
}

.blog-pager a {
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  color: var(--accent-color);
  padding: 0.75rem 1.5rem;
  text-decoration: none;
  font-weight: 500;
  transition: all 0.2s ease;
}

.blog-pager a:hover {
  background: var(--accent-color);
  color: var(--bg);
  border-color: var(--accent-color);
}

/* ============================================
   FOOTER/ATTRIBUTION
   ============================================ */
.Attribution {
  background: var(--bg);
  border-top: 1px solid var(--border-color);
  padding: 3rem 0;
  margin-top: 4rem;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.Attribution a {
  color: var(--accent-color);
  text-decoration: none;
}

.Attribution a:hover {
  text-decoration: underline;
}

/* ============================================
   BUTTONS & INTERACTIVE ELEMENTS
   ============================================ */
.flat-button,
.pill-button {
  background: var(--accent-color);
  color: var(--bg);
  border: none;
  border-radius: var(--radius);
  padding: 0.5rem 1.5rem;
  font-weight: 500;
  cursor: pointer;
  text-transform: uppercase;
  font-size: 0.875rem;
  transition: background-color 0.2s ease;
  display: inline-block;
  text-decoration: none;
}

.flat-button:hover,
.pill-button:hover {
  background: var(--accent-hover);
}

.flat-button.ripple,
.pill-button.ripple {
  position: relative;
  overflow: hidden;
}

/* Jump Link (Read More) */
.jump-link {
  margin-top: 1rem;
}

.jump-link a {
  background: var(--accent-color);
  color: var(--bg);
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius);
  text-decoration: none;
  font-weight: 500;
  display: inline-block;
  transition: background-color 0.2s ease;
}

.jump-link a:hover {
  background: var(--accent-hover);
}

/* ============================================
   RESPONSIVE UTILITIES
   ============================================ */
@media (max-width: 800px) {
  .centered-top {
    flex-wrap: wrap;
    min-height: 4rem;
  }

  .widget.PageList ul {
    display: none; /* Hide on mobile, use hamburger menu */
  }

  #page_body .FeaturedPost,
  .Blog .blog-posts .post-outer-container {
    padding: 1.5rem;
  }

  .post-title {
    font-size: 1.25rem;
  }

  .sidebar_bottom .widget {
    padding: 1rem;
  }
}

/* ============================================
   LOADING & ANIMATIONS
   ============================================ */

/* ============================================
   COMPATIBILITY OVERRIDES
   ============================================ */
a {
  color: var(--accent-color);
  transition: color 0.2s ease;
}

a:hover {
  color: var(--accent-hover);
}

a:visited {
  color: var(--accent-color);
}

/* Ensure all text elements use variable colors */
h1, h2, h3, h4, h5, h6 {
  color: var(--text);
}

p {
  color: var(--text);
}

/* Override any hardcoded background colors */
.widget {
  background: var(--bg-elevated);
  color: var(--text);
}

/* Ensure form inputs use theme colors */
input, textarea, select {
  background: var(--muted);
  color: var(--text);
  border-color: var(--border-color);
}

input:focus, textarea:focus, select:focus {
  border-color: var(--accent-color);
  outline: none;
}

/* Icons should use text color */
svg {
  fill: var(--text);
}

/* Ensure blogger-specific elements use theme */
.blog-pager-older-link, .blog-pager-newer-link {
  color: var(--accent-color);
}

.status-msg-wrap {
  background: var(--bg-elevated);
  border: 1px solid var(--border-color);
  color: var(--text);
  padding: 1rem;
  border-radius: var(--radius);
  margin: 1rem 0;
}

.feed-links {
  display: none; /* Hide RSS feed links for cleaner look */
}
