}

/* HTML/Text widgets for custom About sections */
.sidebar-container .HTML h3,
.sidebar-container .Text h3{
font-size:1.125rem;
margin-bottom:1rem;
}

/* Popular Posts in Sidebar */
.sidebar-container .PopularPosts .item-thumbnail{
float:left;
margin-right:0.75rem;
margin-bottom:0.5rem;
}

.sidebar-container .PopularPosts .item-title{
